<?php declare(strict_types=1);
require __DIR__.'/tax-filings.php';
$attachmentUi=static function(string $name,string $html):void{
    $out=getenv('VEREIN_ATTACHMENT_UI_OUTPUT');if(!$out)return;
    if(!is_dir($out)||!str_starts_with(realpath($out),'/workspace/.local/'))throw new RuntimeException('Private synthetic UI directory required');
    $css=file_get_contents(__DIR__.'/../public/style.css').file_get_contents(__DIR__.'/../public/tax-filings.css');
    file_put_contents($out.'/'.$name.'.html','<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src &#39;none&#39;; style-src &#39;unsafe-inline&#39;; form-action &#39;none&#39;"><title>PDF-Belege · ausschließlich Testdaten</title><style>'.$css.'</style><main style="margin:0;padding:24px">'.$html.'</main></html>');
};
