$receipt['types']['Root']=['simple'=>false,'children'=>[$node('Ordnungsbegriff','Order'),$node('Persoenliche_Daten','Person'),$node('Belege','Evidence')]];
$receipt['types']['Order']=['simple'=>false,'children'=>[$node('Steuernummer','text')]];
$receipt['types']['Person']=['simple'=>false,'children'=>[$node('Person_A','Name')]];
$receipt['types']['Name']=['simple'=>false,'children'=>[$node('SteuerpflichtigerTyp','text'),$node('Name','text')]];
$receipt['types']['Evidence']=['simple'=>false,'children'=>[$node('Jahr','text'),$node('Zeitraum','text'),$node('Text','text'),$node('Steuerarten','Kind',8)]];
$receipt['types']['Kind']=['simple'=>false,'children'=>[$node('Steuerart','text')]];
$cfg['profiles']['Belegnachreichung_24']=$receipt;$cfg['production_versions'][]='Belegnachreichung_24';$cfg['attachment_feedback_enabled']=true;
