$attachments=new TaxAttachments($db,'finance');$selected=$attachments->select([$doc],2025);
$snapshot=['sources'=>[['document_id'=>$doc,'revision'=>$selected[0]['revision'],'sha256'=>$selected[0]['sha256']]]];
check($attachments->fromSnapshot($snapshot,2025)===$selected,'previously selected evidence is inherited without asking twice');
$changedSnapshot=$snapshot;$changedSnapshot['sources'][0]['sha256']=str_repeat('0',64);
denied(fn()=>$attachments->fromSnapshot($changedSnapshot,2025),'inherited evidence must match the approved source snapshot');
check(count($selected)===1&&$attachments->files($selected)[0]['bytes']===$docs->file($doc)['bytes'],'exact attachment bytes selected');
