denied(fn()=>(new TaxAttachments($db,'other'))->select([$doc],2025),'cross-club attachment rejected');
denied(fn()=>$attachments->select(['report:'.str_repeat('a',32)],2025),'unknown report cannot be sent');
$bad=$selected;$bad[0]['sha256']=str_repeat('0',64);denied(fn()=>$attachments->files($bad),'attachment checksum mismatch rejected');
