check(TaxFilingEvidence::needsEvidence(['form_data'=>['auto_preparation'=>['source_snapshot'=>$snapshot]]]),'selected assistant evidence cannot be silently omitted during send');
check(TaxFilingEvidence::needsEvidence(['form_data'=>['auto_preparation'=>['source_snapshot'=>['activity_review'=>['kind'=>'tax','approved'=>true]]]]]),'approved tax report requires the linked evidence step');
check(!TaxFilingEvidence::needsEvidence(['form_data'=>['auto_preparation'=>['source_snapshot'=>['activity_review'=>['kind'=>'assembly','approved'=>true]]]]]),'assembly report never triggers tax transmission');
$child=$bundles->prepare($parent,3);check($bundles->prepare($parent,3)===$child,'one evidence job per declaration');
$cr=$f->get($child);check($cr['environment']==='test'&&$cr['form_data']['parent_binding']['id']===$parent,'child inherits environment and parent reference');
check(!isset($cr['form_data']['fields'][TaxFormSchema::key('Belege/Zeitraum')]),'annual KSt/EUER evidence specifies year without forbidden period field');
denied(fn()=>$f->validate($child,(int)$cr['version']),'empty evidence job blocked');
denied(fn()=>$f->save($child,(int)$cr['version'],['bad'=>'change'],[]),'linked recipient/tax fields cannot be changed independently');
$f->save($child,(int)$cr['version'],[],['feedback_email'=>'test@example.invalid'],null,[$doc]);$cr=$f->get($child);$f->validate($child,(int)$cr['version']);$cr=$f->get($child);
check(str_contains($cr['xml_data'],'RueckmeldungGewuenscht')&&str_contains($cr['xml_data'],'test@example.invalid'),'feedback request and selected email in immutable XML');
check($f->download($child,'attachment-1')['bytes']===$docs->file($doc)['bytes'],'preview opens exact embedded attachment');
