denied(fn()=>$bundles->send($parent,3,'dummy','123456','SEND-TEST',true,true,$child,999),'stale child approval prevents first transport');
check(count($f->attempts($parent))===0,'no parent attempt after child preflight failure');
$attachmentUi('parent',$render(['tax_year'=>'2025','filing'=>$parent],'finance'));
