$sent=$bundles->send($parent,3,'dummy','123456','SEND-TEST',true,true,$child,(int)$cr['version']);
check($sent['state']==='sent_test'&&$sent['evidence']['state']==='sent_test','single reviewed instruction sends parent then selected PDF job');
check(count($f->attempts($parent))===1&&count($f->attempts($child))===1,'separate immutable attempts and receipts');
denied(fn()=>$bundles->send($parent,3,'dummy','123456','SEND-TEST',true,true,$child,(int)$cr['version']),'bundle never sends twice');
