check(count($fb->status($child)['items'])===0&&!str_contains((string)file_get_contents($dir.'/feedback-calls.txt'),'feedback-ack'),'mismatched feedback has no acknowledgement');
$update();$db->exec("CREATE TRIGGER test_feedback_storage_failure BEFORE INSERT ON tax_attachment_feedback FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic storage failure'");
denied(fn()=>$fb->refresh($child,'dummy','123456'),'storage failure aborts feedback acknowledgement');$db->exec('DROP TRIGGER test_feedback_storage_failure');
check(!str_contains((string)file_get_contents($dir.'/feedback-calls.txt'),'feedback-ack'),'no ACK before durable storage');
$update('ack-fail');denied(fn()=>$fb->refresh($child,'dummy','123456'),'failed acknowledgement remains visible');$st=$fb->status($child);
check(count($st['items'])===1&&$st['items'][0]['acknowledged_at']===null,'negative feedback survives ACK failure');
