$parent2=$f->create('TEST_2025','test',2025);$f->save($parent2,1,[$key=>'Changed declaration'],$head);$f->validate($parent2,2);$child2=$bundles->prepare($parent2,3);$f->save($parent2,3,[$key=>'Changed after attachment preparation'],[]);
denied(fn()=>$f->validate($child2,(int)$f->get($child2)['version']),'changed parent invalidates child preparation');
